package com.gameaggregator.apikeyservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.apikeyservice.application.ApiKeyService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api-keys") public class ApiKeyController{final ApiKeyService s;public ApiKeyController(ApiKeyService s){this.s=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED)ApiResponse<ApiKeyDtos.Issued> create(@Valid @RequestBody ApiKeyDtos.Create r){return ApiResponse.success(s.create(r));}@GetMapping ApiResponse<List<ApiKeyDtos.View>> list(@RequestParam(required=false)UUID clientId){return ApiResponse.success(s.list(clientId));}@GetMapping("/{id}")ApiResponse<ApiKeyDtos.View> get(@PathVariable UUID id){return ApiResponse.success(s.get(id));}@PostMapping("/{id}/rotate")ApiResponse<ApiKeyDtos.Issued> rotate(@PathVariable UUID id){return ApiResponse.success(s.rotate(id));}@PostMapping("/{id}/revoke")ApiResponse<ApiKeyDtos.View> revoke(@PathVariable UUID id){return ApiResponse.success(s.revoke(id));}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable UUID id){s.delete(id);}@PostMapping("/verify")ApiResponse<ApiKeyDtos.Verification> verify(@RequestHeader("X-API-Key")String raw){return ApiResponse.success(s.verify(raw));}}